public final class ExposureTimerActivity extends WorkspaceActivity {
    private ScrollView page;private final java.util.ArrayList<Button> durationPresets=new java.util.ArrayList<>();
    private TextView note,inputError,intro;private EditText minutes,partSeconds;private LinearLayout durationControls;private Button cancel;private boolean changingDuration;private boolean validDuration=true;
    private EditText durationField(LinearLayout row,String label,boolean decimal){LinearLayout cell=new LinearLayout(this);cell.setOrientation(1);LinearLayout.LayoutParams box=new LinearLayout.LayoutParams(0,-2,1);if(row.getChildCount()>0)box.leftMargin=dp(20);row.addView(cell,box);TextView title=text(label,13);title.setGravity(Gravity.LEFT);title.setTextColor(UiColors.color(getResources(),0xff9e948c));cell.addView(title);EditText e=new EditText(this);e.setSingleLine(true);e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|(decimal?android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL:0));e.setTextSize(22);e.setTextColor(UiColors.color(getResources(),0xfff2eadf));e.setBackgroundTintList(android.content.res.ColorStateList.valueOf(getResources().getColor(R.color.ui_outline,null)));e.setPadding(0,dp(4),0,dp(4));e.setMinHeight(dp(48));e.setContentDescription("计时"+label);cell.addView(e);return e;}
    private void setDuration(double value){changingDuration=true;minutes.setText(String.valueOf((long)(value/60)));partSeconds.setText(PhotoMath.decimal(value%60));seconds.setText(PhotoMath.decimal(value));changingDuration=false;readDuration();}
    private void readDuration(){if(changingDuration)return;try{double m=Double.parseDouble(minutes.getText().toString()),s=Double.parseDouble(partSeconds.getText().toString());if(!Double.isFinite(m)||m<0||m!=Math.floor(m)||!Double.isFinite(s)||s<0||s>=60)throw new IllegalArgumentException("分钟须为非负整数，秒须小于60");double total=PhotoMath.bounded(m*60+s,1,604800,"计时秒数");seconds.setText(PhotoMath.decimal(total));validDuration=true;inputError.setText("");}catch(Exception bad){seconds.setText("");validDuration=false;inputError.setText("请填写有效时长：至少1秒，秒小于60，最长7天。");}if(start!=null)refresh();}
    private void cancelTimer(){ExposureClock.cancel(this);stopService(new Intent(this,ExposureTimerService.class));getSystemService(NotificationManager.class).cancel(71);refresh();}

    private TextView status,readout;private EditText seconds;private ProgressBar progress;
    private Button start,pause,resume,finish,apply;private LinearLayout root;
    private final Handler handler=new Handler(Looper.getMainLooper());private String priorStatus="";private boolean resumed;
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private Button button(String label,Runnable action){Button b=UiSpacing.button(this);b.setText(label);b.setAllCaps(false);b.setTextColor(UiColors.color(getResources(),0xffef8249));b.setBackgroundTintList(null);android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(UiColors.color(getResources(),0xff30251e));bg.setCornerRadius(dp(12));b.setBackground(bg);b.setMinHeight(dp(48));b.setOnClickListener(v->{try{action.run();refresh();}catch(Exception error){Toast.makeText(this,error.getMessage(),1).show();}});return b;}
    private void primary(Button b){android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(UiColors.color(getResources(),0xfff07f4a));bg.setCornerRadius(dp(12));b.setBackground(bg);b.setTextColor(UiColors.color(getResources(),0xff21170f));b.setTextSize(17);b.setTypeface(android.os.Build.VERSION.SDK_INT>=28?android.graphics.Typeface.create(android.graphics.Typeface.DEFAULT,600,false):android.graphics.Typeface.create("sans-serif-medium",0));b.setLetterSpacing(-.43f/17);b.setMinHeight(dp(50));b.setMinimumHeight(dp(50));b.setPadding(dp(12),dp(6),dp(12),dp(6));}
    private void showActions(){TimerState state=ExposureClock.read(this);boolean active=state.status.equals("running")||state.status.equals("paused");new AlertDialog.Builder(this).setItems(active?new String[]{"取消计时","通知设置"}:new String[]{"通知设置"},(d,which)->{if(active&&which==0){cancelTimer();}else enableNotifications();}).show();}
    private TextView text(String label,int size){TextView v=new TextView(this);v.setText(label);v.setTextColor(UiColors.color(getResources(),0xfff2eadf));v.setTextSize(size);v.setGravity(Gravity.CENTER);return v;}
    private void gap(LinearLayout parent,int size){parent.addView(new View(this),new LinearLayout.LayoutParams(1,dp(size)));}
    private void icon(Button button,int code,boolean filled,String label){android.text.SpannableString value=new android.text.SpannableString(String.valueOf((char)code)+"  "+label);android.graphics.Typeface font=android.graphics.Typeface.createFromAsset(getAssets(),filled?"fonts/Phosphor-Fill.ttf":"fonts/Phosphor.ttf");value.setSpan(new android.text.style.MetricAffectingSpan(){private void set(android.text.TextPaint paint){paint.setTypeface(font);}public void updateDrawState(android.text.TextPaint paint){set(paint);}public void updateMeasureState(android.text.TextPaint paint){set(paint);}},0,1,0);value.setSpan(new android.text.style.RelativeSizeSpan(20f/17),0,1,0);button.setText(value);button.setContentDescription(label);}
    @Override public void onCreate(Bundle saved){
        super.onCreate(saved);root=new LinearLayout(this);root.setOrientation(1);root.setClipToPadding(false);root.setPadding(dp(16),0,dp(16),dp(8));root.setBackgroundColor(UiColors.color(getResources(),0xff1f1612));setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(dp(16),i.getSystemWindowInsetTop(),dp(16),dp(8)+i.getSystemWindowInsetBottom());return i;});root.requestApplyInsets();
        View nav=LibraryUi.header(this,"长曝光",this::requestBack,LibraryUi.icon(this,0xe1fe,"更多计时操作",this::showActions),16);TextView navTitle=nav.findViewWithTag("library-header-title");navTitle.setAlpha(0);navTitle.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);root.addView(nav);
        ScrollView scroll=new ScrollView(this);page=scroll;final int restoreY=saved==null?0:saved.getInt("scrollY");scroll.post(()->scroll.scrollTo(0,restoreY));LinearLayout body=new LinearLayout(this);body.setOrientation(1);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));TextView heading=text("长曝光",30);heading.setGravity(Gravity.LEFT);heading.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);heading.setLetterSpacing(.4f/30);heading.setPadding(0,dp(12),0,dp(14));heading.setLineSpacing(0,1.15f);body.addView(heading);
        scroll.setOnScrollChangeListener((view,x,y,oldX,oldY)->{boolean titleFits=getResources().getConfiguration().fontScale<=1.3f||getResources().getConfiguration().screenWidthDp>=400;boolean visible=y>dp(40)&&titleFits;if(visible==(oldY>dp(40)&&titleFits))return;navTitle.animate().cancel();navTitle.setImportantForAccessibility(visible?View.IMPORTANT_FOR_ACCESSIBILITY_YES:View.IMPORTANT_FOR_ACCESSIBILITY_NO);boolean reduced=android.provider.Settings.Global.getFloat(getContentResolver(),android.provider.Settings.Global.ANIMATOR_DURATION_SCALE,1)==0;navTitle.animate().alpha(visible?1:0).setDuration(reduced?0:200).setInterpolator(new android.view.animation.LinearInterpolator()).start();});
        LinearLayout instrument=new LinearLayout(this);instrument.setOrientation(1);instrument.setPadding(dp(18),dp(22),dp(18),dp(18));android.graphics.drawable.GradientDrawable panel=new android.graphics.drawable.GradientDrawable();panel.setColor(android.graphics.Color.TRANSPARENT);panel.setCornerRadius(dp(18));instrument.setBackground(panel);instrument.setClipToOutline(true);body.addView(instrument,new LinearLayout.LayoutParams(-1,-2));readout=text("0:00",60);readout.setTypeface(Build.VERSION.SDK_INT>=28?android.graphics.Typeface.create(android.graphics.Typeface.MONOSPACE,500,false):android.graphics.Typeface.MONOSPACE);readout.setFontFeatureSettings("tnum");readout.setIncludeFontPadding(false);readout.setLetterSpacing(-.02f);readout.setMaxLines(1);readout.setAutoSizeTextTypeUniformWithConfiguration(24,60,1,android.util.TypedValue.COMPLEX_UNIT_SP);instrument.addView(readout,new LinearLayout.LayoutParams(-1,-2));gap(instrument,16);
        progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(10000);android.graphics.drawable.GradientDrawable track=new android.graphics.drawable.GradientDrawable(),fill=new android.graphics.drawable.GradientDrawable();track.setColor(UiColors.color(getResources(),0x21e8906a));track.setCornerRadius(dp(3));fill.setColor(UiColors.color(getResources(),0xfff07f4a));fill.setCornerRadius(dp(3));android.graphics.drawable.LayerDrawable bars=new android.graphics.drawable.LayerDrawable(new android.graphics.drawable.Drawable[]{track,new android.graphics.drawable.ClipDrawable(fill,Gravity.LEFT,android.graphics.drawable.ClipDrawable.HORIZONTAL)});bars.setId(0,android.R.id.background);bars.setId(1,android.R.id.progress);progress.setProgressDrawable(bars);instrument.addView(progress,new LinearLayout.LayoutParams(-1,dp(6)));gap(instrument,12);status=text("准备就绪",15);instrument.addView(status);
        gap(body,12);intro=text("设定时长，手动打开快门后开始计时。",13);intro.setTextColor(UiColors.color(getResources(),0xff9e948c));body.addView(intro);gap(body,24);
        seconds=new EditText(this);durationControls=new LinearLayout(this);durationControls.setOrientation(1);body.addView(durationControls);LinearLayout fields=new LinearLayout(this);fields.setPadding(dp(30),0,dp(30),0);durationControls.addView(fields);minutes=durationField(fields,"分钟",false);partSeconds=durationField(fields,"秒",true);
        inputError=text("",13);inputError.setTextColor(getResources().getColor(R.color.ui_error,null));inputError.setMinHeight(dp(24));inputError.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);body.addView(inputError);
        double initial=30;try{initial=Double.parseDouble(saved!=null?saved.getString("seconds","30"):PhotoMath.decimal(getIntent().getLongExtra("duration_ms",30000)/1000.0));}catch(Exception ignored){}setDuration(initial);if(saved!=null&&saved.containsKey("minutes")){changingDuration=true;minutes.setText(saved.getString("minutes"));partSeconds.setText(saved.getString("partSeconds"));changingDuration=false;readDuration();}
        if(getIntent().hasExtra("duration_ms")){minutes.setEnabled(false);partSeconds.setEnabled(false);TextView source=text("来自计算结果",12);source.setTextColor(UiColors.color(getResources(),0xff9e948c));durationControls.addView(source);}else{boolean stacked=getResources().getConfiguration().fontScale>1.3f&&getResources().getConfiguration().screenWidthDp<400;LinearLayout presets=new LinearLayout(this);presets.setOrientation(stacked?1:0);gap(durationControls,12);durationControls.addView(presets);LinearLayout presetRow=presets;for(int index=0;index<4;index++){if(stacked&&index%2==0){presetRow=new LinearLayout(this);presets.addView(presetRow);}final int value=new int[]{15,30,60,120}[index];Button preset=button(new String[]{"15秒","30秒","1分钟","2分钟"}[index],()->setDuration(value));preset.setTag(value);durationPresets.add(preset);preset.setTextSize(14);preset.setPadding(dp(4),dp(4),dp(4),dp(4));presetRow.addView(preset,new LinearLayout.LayoutParams(0,-2,1));}}
        android.text.TextWatcher edit=new android.text.TextWatcher(){public void beforeTextChanged(CharSequence text,int start,int count,int after){}public void onTextChanged(CharSequence text,int start,int before,int count){readDuration();}public void afterTextChanged(android.text.Editable text){}};minutes.addTextChangedListener(edit);partSeconds.addTextChangedListener(edit);
        gap(body,16);Button help=button("计时与后台说明 ›",()->new AlertDialog.Builder(this).setTitle("计时与后台说明").setMessage("暂停会延长实际曝光，请先关闭快门。返回后可继续后台计时；手机重启会中断。手机仅计时，不会控制相机快门。").setPositiveButton("知道了",null).show());help.setBackgroundColor(android.graphics.Color.TRANSPARENT);body.addView(help);
        note=text("手机仅计时，需手动开合相机快门。",13);note.setTextColor(UiColors.color(getResources(),0xff9e948c));note.setPadding(0,dp(8),0,dp(8));root.addView(note);
        LinearLayout controls=new LinearLayout(this);controls.setPadding(0,dp(10),0,0);root.addView(controls);
        start=button("开始计时",()->{double value=Double.parseDouble(seconds.getText().toString());PhotoMath.bounded(value,1,604800,"计时秒数");ExposureClock.begin(this,Math.round(value*1000));runService();root.performHapticFeedback(HapticFeedbackConstants.CONTEXT_CLICK);});icon(start,0xe3d0,true,"开始计时");primary(start);controls.addView(start,new LinearLayout.LayoutParams(0,-2,1));
        pause=button("暂停",()->{ExposureClock.pause(this);stopService(new Intent(this,ExposureTimerService.class));root.performHapticFeedback(HapticFeedbackConstants.CLOCK_TICK);});icon(pause,0xe39e,true,"暂停");primary(pause);controls.addView(pause,new LinearLayout.LayoutParams(0,-2,1));
        resume=button("继续",()->{ExposureClock.resume(this);runService();root.performHapticFeedback(HapticFeedbackConstants.CONTEXT_CLICK);});icon(resume,0xe3d0,true,"继续");primary(resume);controls.addView(resume,new LinearLayout.LayoutParams(0,-2,1));
        apply=button("记录这次曝光",()->{TimerState state=ExposureClock.read(this);if(!state.status.equals("finished"))return;Intent answer=new Intent().putExtra("shutter",PhotoMath.shutterChoice(state.total/1000.0));String aperture=getIntent().getStringExtra("aperture");if(aperture!=null&&!aperture.isEmpty())answer.putExtra("aperture",aperture);setResult(RESULT_OK,answer);acknowledgeAndFinish();});icon(apply,0xe10e,false,"记录这次曝光");primary(apply);controls.addView(apply,new LinearLayout.LayoutParams(0,-2,1));
        finish=button("完成",this::acknowledgeAndFinish);primary(finish);controls.addView(finish,new LinearLayout.LayoutParams(0,-2,1));
        if(getResources().getConfiguration().fontScale>1.3f&&getResources().getConfiguration().screenWidthDp<400){controls.setOrientation(1);for(int i=0;i<controls.getChildCount();i++)controls.getChildAt(i).setLayoutParams(new LinearLayout.LayoutParams(-1,-2));}
        cancel=button("取消计时",this::cancelTimer);cancel.setBackgroundColor(android.graphics.Color.TRANSPARENT);root.addView(cancel,new LinearLayout.LayoutParams(-1,-2));

    }
    private void acknowledgeAndFinish(){ExposureClock.acknowledgeCompletion(this);stopService(new Intent(this,ExposureTimerService.class));getSystemService(NotificationManager.class).cancel(71);finish();}
    private void requestBack(){String state=ExposureClock.read(this).status;if(state.equals("running")||state.equals("paused"))new AlertDialog.Builder(this).setTitle(state.equals("running")?"返回并继续计时？":"返回并保留暂停？").setMessage(state.equals("running")?"长曝光计时仍在运行。返回后会在后台继续，请在计时结束时手动关闭相机快门。":"计时已暂停，返回后保持暂停；再次进入可继续或取消。").setNegativeButton("留在此页",null).setPositiveButton("返回",(dialog,which)->finish()).show();else finish();}
    @Override public void onBackPressed(){requestBack();}
    private void enableNotifications(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},72);else{ExposureTimerService.channels(this);startActivity(new Intent(android.provider.Settings.ACTION_CHANNEL_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE,getPackageName()).putExtra(android.provider.Settings.EXTRA_CHANNEL_ID,ExposureTimerService.COMPLETION_CHANNEL));}}
    private void runService(){try{startForegroundService(new Intent(this,ExposureTimerService.class));}catch(RuntimeException error){ExposureClock.pause(this);throw error;}}
    private void refresh(){
        TimerState s=ExposureClock.read(this);boolean running=s.status.equals("running"),paused=s.status.equals("paused"),completed=s.status.equals("finished"),active=running||paused;
        intro.setVisibility(!active&&!completed?View.VISIBLE:View.GONE);durationControls.setVisibility(!active&&!completed?View.VISIBLE:View.GONE);inputError.setVisibility(!active&&!completed?View.VISIBLE:View.GONE);cancel.setVisibility(active?View.VISIBLE:View.GONE);start.setEnabled(validDuration);note.setText(running?"暂停前先关闭快门；手机不会控制相机。":"手机仅计时，需手动开合相机快门。");start.setVisibility(!active&&!completed?View.VISIBLE:View.GONE);pause.setVisibility(running?View.VISIBLE:View.GONE);resume.setVisibility(paused?View.VISIBLE:View.GONE);finish.setVisibility(completed?View.VISIBLE:View.GONE);apply.setVisibility(completed&&getIntent().getBooleanExtra("return_result",false)?View.VISIBLE:View.GONE);
        if(active||completed){String value=PhotoMath.decimal(s.total/1000.0);if(!seconds.getText().toString().equals(value)){changingDuration=true;seconds.setText(value);minutes.setText(String.valueOf(s.total/60000));partSeconds.setText(PhotoMath.decimal((s.total%60000)/1000.0));changingDuration=false;}}long selected=0;try{double value=Double.parseDouble(seconds.getText().toString());if(Double.isFinite(value)&&value>=0&&value<=604800)selected=Math.round(value*1000);}catch(NumberFormatException ignored){}long duration=active||completed?s.total:selected;long remaining=active||completed?s.remaining:Math.max(0,duration);for(Button preset:durationPresets){boolean selectedPreset=validDuration&&Math.abs(duration-((Integer)preset.getTag())*1000L)<1;if(preset.isSelected()!=selectedPreset){preset.setSelected(selectedPreset);android.graphics.drawable.GradientDrawable fill=new android.graphics.drawable.GradientDrawable();fill.setColor(getResources().getColor(selectedPreset?R.color.ui_selected:R.color.ui_card,null));fill.setCornerRadius(dp(8));preset.setBackground(fill);preset.setContentDescription(preset.getText()+(selectedPreset?"，已选":""));}}String main=TimerState.duration(remaining);android.text.SpannableString value=new android.text.SpannableString(main+(active||completed?" / "+TimerState.duration(Math.max(0,duration)):""));if(value.length()>main.length()){value.setSpan(new android.text.style.RelativeSizeSpan(.4f),main.length(),value.length(),0);value.setSpan(new android.text.style.ForegroundColorSpan(UiColors.color(getResources(),0xff9e948c)),main.length(),value.length(),0);}readout.setText(!active&&!completed&&!validDuration?"—":value);progress.setProgress(completed?10000:active&&s.total>0?(int)(10000d*(s.total-s.remaining)/s.total):0);
        status.setText(running?"计时中":paused?"已暂停":completed?"曝光完成，请关闭快门":s.status.equals("interrupted")?"手机重启，计时已中断":s.status.equals("cancelled")?"已取消":"准备就绪");
        if(completed&&priorStatus.equals("running")){root.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);handler.postDelayed(()->{if(resumed)root.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);},300);}priorStatus=s.status;
    }
    private final Runnable tick=new Runnable(){public void run(){refresh();handler.postDelayed(this,100);}};
    @Override protected void onResume(){super.onResume();resumed=true;if(ExposureClock.needsService(this))runService();handler.post(tick);}
    @Override protected void onPause(){resumed=false;handler.removeCallbacks(tick);super.onPause();}
    @Override protected void onSaveInstanceState(Bundle out){out.putInt("scrollY",page==null?0:page.getScrollY());out.putString("seconds",seconds.getText().toString());out.putString("minutes",minutes.getText().toString());out.putString("partSeconds",partSeconds.getText().toString());super.onSaveInstanceState(out);}
}
